public int findMinArrowShots(int[][] points) {
    if (points.length == 0) return 0;

    // Sort by END; Integer.compare avoids a-b overflow at int extremes.
    Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));

    int arrows = 1;
    int arrowAt = points[0][1];          // fire at the earliest end
    for (int i = 1; i < points.length; i++) {
        if (points[i][0] > arrowAt) {    // strict: touching balloons share an arrow
            arrows++;
            arrowAt = points[i][1];
        }
    }
    return arrows;
}

